// Helper functions for filtering and statistics
export const getProblemsByCategory = (category) => {
  return dsa250Problems.filter(p => p.category === category);
};

export const getProblemsByDifficulty = (difficulty) => {
  return dsa250Problems.filter(p => p.difficulty === difficulty);
};

export const getProblemsByCompany = (company) => {
  return dsa250Problems.filter(p => p.companies.includes(company));
};

export const getSolvedProblems = () => {
  return dsa250Problems.filter(p => p.solved);
};

export const getUnsolvedProblems = () => {
  return dsa250Problems.filter(p => !p.solved);
};

export const getProgressStats = () => {
  const total = dsa250Problems.length;
  const solved = dsa250Problems.filter(p => p.solved).length;
  const easy = dsa250Problems.filter(p => p.difficulty === 'Easy' && p.solved).length;
  const medium = dsa250Problems.filter(p => p.difficulty === 'Medium' && p.solved).length;
  const hard = dsa250Problems.filter(p => p.difficulty === 'Hard' && p.solved).length;
  
  return {
    total,
    solved,
    unsolved: total - solved,
    percentage: ((solved / total) * 100).toFixed(1),
    byDifficulty: { easy, medium, hard }
  };
};

export const getCategoryStats = () => {
  const categories = [...new Set(dsa250Problems.map(p => p.category))];
  return categories.map(category => {
    const problems = dsa250Problems.filter(p => p.category === category);
    const solved = problems.filter(p => p.solved).length;
    return {
      category,
      total: problems.length,
      solved,
      unsolved: problems.length - solved,
      percentage: ((solved / problems.length) * 100).toFixed(1)
    };
  });
};

export const getTopCompanies = () => {
  const companyCount = {};
  dsa250Problems.forEach(problem => {
    problem.companies.forEach(company => {
      companyCount[company] = (companyCount[company] || 0) + 1;
    });
  });
  
  return Object.entries(companyCount)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10)
    .map(([company, count]) => ({ company, count }));
};
